// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MY_BANK c;

    function setUp() public {
        c = new MY_BANK(address(new Log()));
    }

    function testFuzz_property(uint256 balance, uint256 collectAmount) public {
        vm.assume(balance <= VALUE_CAP);
        address actor = address(0xBEEF);

        // Put enough ETH so that the holder's stored balance is exactly `balance`.
        balance = bound(balance, 1 ether, 100 ether);
        vm.deal(actor, balance);
        vm.prank(actor);
        c.Put{value: balance}(0);

        // Keep collectAmount <= balance so the internal condition `acc.balance >= _am` passes.
        collectAmount = bound(collectAmount, 0, balance);

        // Record the pre-collect stored balance and unlock time.
        (uint256 unlockTime, uint256 beforeBalance) = c.Acc(actor);
        uint256 beforeContractBalance = address(c).balance;

        // Warp past the unlock time so Collect can proceed.
        vm.warp(unlockTime + 1);

        // Ensure the actor can call Collect payable (no value needed, but payable is fine).
        vm.prank(actor);
        c.Collect(collectAmount);

        // After a successful Collect, the stored balance must be beforeBalance - collectAmount.
        (, uint256 afterBalance) = c.Acc(actor);
        uint256 afterContractBalance = address(c).balance;

        // The reference contract satisfies this for all admissible inputs:
        // stored balance decreases by exactly collectAmount, and the contract's ETH balance decreases by exactly collectAmount.
        assertTrue(
            afterBalance == beforeBalance - collectAmount &&
            afterContractBalance == beforeContractBalance - collectAmount
        );
    }
}
